import json
from datetime import datetime


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        rows = json.loads(text)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON")

    if not isinstance(rows, list):
        raise ValueError("Input must be a JSON array")

    if not rows:
        return {"row_count": 0, "total_cents": 0, "first_day": None, "last_day": None}

    dates = []
    total = 0

    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("Each row must be an object")

        if not isinstance(row.get("tenant"), str) or not row["tenant"]:
            raise ValueError("Tenant must be a nonempty string")

        if not isinstance(row.get("amount_cents"), int) or isinstance(row.get("amount_cents"), bool):
            raise ValueError("amount_cents must be an integer")

        day = row.get("day")
        if not isinstance(day, str):
            raise ValueError("Day must be a string")
        if len(day) != 10 or day[:4] != "20" or day[5:7] != "-":
            raise ValueError("Day must be in YYYY-MM-DD format")

        try:
            datetime.strptime(day, "%Y-%m-%d")
        except ValueError:
            raise ValueError(f"Invalid date: {day}")

        total += row["amount_cents"]
        dates.append(day)

    sorted_dates = sorted(dates)
    return {
        "row_count": len(rows),
        "total_cents": total,
        "first_day": sorted_dates[0],
        "last_day": sorted_dates[-1],
    }"}

